import { OpenAPIHono, createRoute, z } from '@hono/zod-openapi';
import { Bindings, Variables } from '../../../bindings';
import { ROUTE_METADATA } from '../../../_shared/constants/route_metadata';

const r = new OpenAPIHono<{ Bindings: Bindings; Variables: Variables }>();

const getPayoutHistoryRoute = createRoute({
    ...ROUTE_METADATA.PSW_EXTRA.PAYOUT_HISTORY,
    method: 'get',
    path: '/history',
    responses: {
        200: {
            content: {
                'application/json': {
                    schema: z.array(z.object({
                        id: z.string(),
                        amount: z.any(),
                        currency: z.string(),
                        status: z.string(),
                        createdAt: z.date(),
                        processedAt: z.date().nullable()
                    })),
                },
            },
            description: 'Payout history retrieved successfully',
        },
        404: {
            content: {
                'application/json': {
                    schema: z.object({ error: z.string() }),
                },
            },
            description: 'Resource not found',
        },
    },
});

r.openapi(getPayoutHistoryRoute, async (c) => {
    const prisma = c.get('prisma');
    const user = c.get('user');

    const pswProfile = await prisma.pswProfile.findUnique({
        where: { userId: user.id }
    });

    if (!pswProfile) {
        return c.json({ error: 'PSW profile not found' }, 404);
    }

    const payouts = await prisma.payout.findMany({
        where: { pswId: pswProfile.id },
        orderBy: { createdAt: 'desc' }
    });

    return c.json(payouts, 200);
});

export default r;
